-- description: DANE national total CPI index, base December 2018 = 100, one row per month.
SELECT year, month, ipc_index
FROM {{ source('dane_ipc_index') }}

-- description: Macroeconomic context by fiscal year: December CPI index and inflation, TRM average and 31 December rate.
SELECT fiscal_year, ipc_dec_index, inflation_dec_yoy, trm_avg, trm_dec31
FROM {{ ref('int_macro_year') }}
